import { spawn } from 'child_process'
import path from 'path'

import { describe, test, expect, beforeAll } from 'bun:test'
import stripAnsi from 'strip-ansi'

import {
  isTmuxAvailable,
  isSDKBuilt,
  sleep,
  ensureCliTestEnv,
  getDefaultCliEnv,
} from './test-utils'

const CLI_PATH = path.join(__dirname, '../index.tsx')
const TIMEOUT_MS = 15000
const tmuxAvailable = isTmuxAvailable()
const sdkBuilt = isSDKBuilt()

ensureCliTestEnv()

// Utility to run tmux commands
function tmux(args: string[]): Promise<string> {
  return new Promise((resolve, reject) => {
    const proc = spawn('tmux', args, { stdio: 'pipe' })
    let stdout = ''
    let stderr = ''

    proc.stdout?.on('data', (data) => {
      stdout += data.toString()
    })

    proc.stderr?.on('data', (data) => {
      stderr += data.toString()
    })

    proc.on('close', (code) => {
      if (code === 0) {
        resolve(stdout)
      } else {
        reject(new Error(`tmux command failed: ${stderr}`))
      }
    })
  })
}

describe.skipIf(!tmuxAvailable || !sdkBuilt)(
  'CLI Integration Tests with tmux',
  () => {
    beforeAll(async () => {
      if (!tmuxAvailable) {
        console.log('\n⚠️  Skipping tmux tests - tmux not installed')
        console.log(
          '📦 Install with: brew install tmux (macOS) or sudo apt-get install tmux (Linux)\n',
        )
      }
      if (!sdkBuilt) {
        console.log('\n⚠️  Skipping tmux tests - SDK not built')
        console.log('🔨 Build SDK: cd sdk && bun run build\n')
      }
      if (tmuxAvailable && sdkBuilt) {
        const envVars = getDefaultCliEnv()
        const entries = Object.entries(envVars)
        // Propagate environment into tmux server so sessions inherit required vars
        await Promise.all(
          entries.map(([key, value]) =>
            tmux(['set-environment', '-g', key, value]).catch(() => {
              // Ignore failures; environment might already be set
            }),
          ),
        )
        // Clear SAVANT_FREE_MODE from the tmux global env. A previous savant-free
        // build or `bun run dev:savant-free` invocation in the same tmux server
        // can leave it set globally, which would make this test see the
        // savant-free CLI variant (which has no `--agent` flag).
        await tmux(['set-environment', '-gu', 'SAVANT_FREE_MODE']).catch(() => {})
      }
    })

    test(
      'CLI starts and displays help output',
      async () => {
        const sessionName = 'savant-code-test-' + Date.now()

        try {
          // Create session with --help flag and keep it alive with '; sleep 2'
          await tmux([
            'new-session',
            '-d',
            '-s',
            sessionName,
            '-x',
            '120',
            '-y',
            '30',
            `bun run ${CLI_PATH} --help; sleep 2`,
          ])

          // Wait for output - give CLI time to start and render help
          await sleep(800)

          let cleanOutput = ''
          for (let i = 0; i < 10; i += 1) {
            await sleep(300)
            const output = await tmux(['capture-pane', '-t', sessionName, '-p'])
            cleanOutput = stripAnsi(output)
            if (cleanOutput.includes('--agent')) {
              break
            }
          }

          expect(cleanOutput).toContain('--agent')
          expect(cleanOutput).toContain('Usage:')
        } finally {
          // Cleanup
          try {
            await tmux(['kill-session', '-t', sessionName])
          } catch {
            // Session may have already exited
          }
        }
      },
      TIMEOUT_MS,
    )

    test(
      'CLI accepts --agent flag',
      async () => {
        const sessionName = 'savant-code-test-' + Date.now()

        try {
          // Start CLI with --agent flag (it will wait for input, so we can capture)
          await tmux([
            'new-session',
            '-d',
            '-s',
            sessionName,
            '-x',
            '120',
            '-y',
            '30',
            `bun run ${CLI_PATH} --agent ask`,
          ])

          let output = ''
          for (let i = 0; i < 5; i += 1) {
            await sleep(200)
            output = await tmux(['capture-pane', '-t', sessionName, '-p'])
            if (output.length > 0) {
              break
            }
          }

          // Should have started without errors
          expect(output.length).toBeGreaterThan(0)
        } finally {
          try {
            await tmux(['kill-session', '-t', sessionName])
          } catch {
            // Session may have already exited
          }
        }
      },
      TIMEOUT_MS,
    )
  },
)

// Always show installation message when tmux tests are skipped
if (!tmuxAvailable) {
  describe('tmux Installation Required', () => {
    test.skip('Install tmux for interactive CLI tests', () => {
      // This test is intentionally skipped to show the message
    })
  })
}

if (!sdkBuilt) {
  describe('SDK Build Required', () => {
    test.skip('Build SDK for integration tests: cd sdk && bun run build', () => {
      // This test is intentionally skipped to show the message
    })
  })
}

import { spawn } from 'child_process'
import path from 'path'

import { describe, test, expect, beforeAll } from 'bun:test'

import {
  isTmuxAvailable,
  isSDKBuilt,
  sleep,
  ensureCliTestEnv,
  getDefaultCliEnv,
  parseRerenderLogs,
  analyzeRerenders,
  clearCliDebugLog,
} from './test-utils'

const CLI_PATH = path.join(__dirname, '../index.tsx')
const DEBUG_LOG_PATH = path.join(__dirname, '../../../debug/cli.jsonl')
const TIMEOUT_MS = 45000
const tmuxAvailable = isTmuxAvailable()
const sdkBuilt = isSDKBuilt()

ensureCliTestEnv()

/**
 * Re-render performance thresholds.
 * These values are based on observed behavior after optimization.
 * If these thresholds are exceeded, it likely indicates a performance regression.
 */
const RERENDER_THRESHOLDS = {
  /** Maximum total re-renders across all messages for a simple prompt */
  maxTotalRerenders: 20,

  /** Maximum re-renders for any single message */
  maxRerenderPerMessage: 12,

  /**
   * Props that should NEVER appear in changedProps after memoization fixes.
   * If these appear, it means callbacks are not properly memoized.
   */
  forbiddenChangedProps: [
    'onOpenFeedback',
    'onToggleCollapsed',
    'onBuildFast',
    'onBuildMax',
    'onBuildLite',
    'onCloseFeedback',
  ],

  /**
   * Maximum times streamingAgents should appear in changedProps.
   * After Set stabilization, this should be very low.
   */
  maxStreamingAgentChanges: 5,
}

// Utility to run tmux commands
function tmux(args: string[]): Promise<string> {
  return new Promise((resolve, reject) => {
    const proc = spawn('tmux', args, { stdio: 'pipe' })
    let stdout = ''
    let stderr = ''

    proc.stdout?.on('data', (data) => {
      stdout += data.toString()
    })

    proc.stderr?.on('data', (data) => {
      stderr += data.toString()
    })

    proc.on('close', (code) => {
      if (code === 0) {
        resolve(stdout)
      } else {
        reject(new Error(`tmux command failed: ${stderr}`))
      }
    })
  })
}

/**
 * Send input to the CLI using bracketed paste mode.
 * Standard send-keys doesn't work with OpenTUI - see tmux.knowledge.md
 */
async function sendCliInput(sessionName: string, text: string): Promise<void> {
  await tmux([
    'send-keys',
    '-t',
    sessionName,
    '-l',
    `\x1b[200~${text}\x1b[201~`,
  ])
}

describe.skipIf(!tmuxAvailable || !sdkBuilt)(
  'Re-render Performance Tests',
  () => {
    beforeAll(async () => {
      if (!tmuxAvailable) {
        console.log('\n⚠️  Skipping re-render perf tests - tmux not installed')
        console.log(
          '📦 Install with: brew install tmux (macOS) or sudo apt-get install tmux (Linux)\n',
        )
      }
      if (!sdkBuilt) {
        console.log('\n⚠️  Skipping re-render perf tests - SDK not built')
        console.log('🔨 Build SDK: cd sdk && bun run build\n')
      }
      if (tmuxAvailable && sdkBuilt) {
        const envVars = getDefaultCliEnv()
        const entries = Object.entries(envVars)
        // Propagate environment into tmux server
        await Promise.all(
          entries.map(([key, value]) =>
            tmux(['set-environment', '-g', key, value]),
          ),
        )
        // Enable performance testing
        await tmux(['set-environment', '-g', 'SAVANT_CODE_PERF_TEST', 'true'])
      }
    })

    test(
      'MessageBlock re-renders stay within acceptable limits',
      async () => {
        const sessionName = 'savant-code-perf-test-' + Date.now()

        // Clear the debug log before test
        clearCliDebugLog(DEBUG_LOG_PATH)

        try {
          // Start CLI with perf testing enabled
          await tmux([
            'new-session',
            '-d',
            '-s',
            sessionName,
            '-x',
            '120',
            '-y',
            '30',
            `SAVANT_CODE_PERF_TEST=true bun run ${CLI_PATH}`,
          ])

          // Wait for CLI to initialize
          await sleep(5000)

          // Send a simple prompt that will trigger streaming response
          await sendCliInput(sessionName, 'what is 2+2')
          await tmux(['send-keys', '-t', sessionName, 'Enter'])

          // Wait for response to complete (longer wait for API response)
          await sleep(15000)

          // Parse and analyze the re-render logs
          const entries = parseRerenderLogs(DEBUG_LOG_PATH)
          const analysis = analyzeRerenders(entries)

          // Log analysis for debugging
          console.log('\n📊 Re-render Analysis:')
          console.log(`   Total re-renders: ${analysis.totalRerenders}`)
          console.log(`   Max per message: ${analysis.maxRerenderPerMessage}`)
          console.log(
            `   Messages tracked: ${analysis.rerendersByMessage.size}`,
          )
          if (analysis.propChangeFrequency.size > 0) {
            console.log('   Prop change frequency:')
            for (const [prop, count] of analysis.propChangeFrequency) {
              console.log(`     - ${prop}: ${count}`)
            }
          }

          // Assert total re-renders within threshold
          expect(analysis.totalRerenders).toBeLessThanOrEqual(
            RERENDER_THRESHOLDS.maxTotalRerenders,
          )

          // Assert max re-renders per message within threshold
          expect(analysis.maxRerenderPerMessage).toBeLessThanOrEqual(
            RERENDER_THRESHOLDS.maxRerenderPerMessage,
          )

          // Assert forbidden props don't appear (memoization check)
          for (const forbiddenProp of RERENDER_THRESHOLDS.forbiddenChangedProps) {
            const count = analysis.propChangeFrequency.get(forbiddenProp) || 0
            if (count > 0) {
              console.log(
                `\n❌ Forbidden prop '${forbiddenProp}' changed ${count} times - callback not memoized!`,
              )
            }
            expect(count).toBe(0)
          }

          // Assert streamingAgents changes within threshold
          const streamingAgentChanges =
            analysis.propChangeFrequency.get('streamingAgents') || 0
          expect(streamingAgentChanges).toBeLessThanOrEqual(
            RERENDER_THRESHOLDS.maxStreamingAgentChanges,
          )

          console.log('\n✅ Re-render performance within acceptable limits')
        } finally {
          // Cleanup tmux session
          try {
            await tmux(['kill-session', '-t', sessionName])
          } catch {
            // Session may have already exited
          }
        }
      },
      TIMEOUT_MS,
    )

    test(
      'Forbidden callback props are properly memoized',
      async () => {
        const sessionName = 'savant-code-memo-test-' + Date.now()

        clearCliDebugLog(DEBUG_LOG_PATH)

        try {
          await tmux([
            'new-session',
            '-d',
            '-s',
            sessionName,
            '-x',
            '120',
            '-y',
            '30',
            `SAVANT_CODE_PERF_TEST=true bun run ${CLI_PATH}`,
          ])

          await sleep(5000)

          // Send multiple rapid prompts to stress test memoization
          await sendCliInput(sessionName, 'hi')
          await tmux(['send-keys', '-t', sessionName, 'Enter'])
          await sleep(8000)

          const entries = parseRerenderLogs(DEBUG_LOG_PATH)
          const analysis = analyzeRerenders(entries)

          // Check that none of the callback props appear in changed props
          const forbiddenPropsFound: string[] = []
          for (const prop of RERENDER_THRESHOLDS.forbiddenChangedProps) {
            const count = analysis.propChangeFrequency.get(prop) || 0
            if (count > 0) {
              forbiddenPropsFound.push(`${prop} (${count}x)`)
            }
          }

          if (forbiddenPropsFound.length > 0) {
            console.log(
              `\n❌ Unmemoized callbacks detected: ${forbiddenPropsFound.join(', ')}`,
            )
          }

          expect(forbiddenPropsFound).toHaveLength(0)
        } finally {
          try {
            await tmux(['kill-session', '-t', sessionName])
          } catch {}
        }
      },
      TIMEOUT_MS,
    )
  },
)

// Show helpful message when tests are skipped
if (!tmuxAvailable) {
  describe('Re-render Performance - tmux Required', () => {
    test.skip('Install tmux for performance tests', () => {})
  })
}

if (!sdkBuilt) {
  describe('Re-render Performance - SDK Required', () => {
    test.skip('Build SDK: cd sdk && bun run build', () => {})
  })
}

#!/usr/bin/env bun

/**
 * Proof of Concept: tmux-based CLI testing
 *
 * This script demonstrates how to:
 * 1. Create a tmux session
 * 2. Run the CLI in that session
 * 3. Send commands to the CLI
 * 4. Capture and verify output
 * 5. Clean up the session
 */

import { spawn } from 'child_process'

import stripAnsi from 'strip-ansi'

import { isTmuxAvailable, sleep } from './test-utils'

// Utility to run tmux commands
function tmux(args: string[]): Promise<string> {
  return new Promise((resolve, reject) => {
    const proc = spawn('tmux', args, { stdio: 'pipe' })
    let stdout = ''
    let stderr = ''

    proc.stdout?.on('data', (data) => {
      stdout += data.toString()
    })

    proc.stderr?.on('data', (data) => {
      stderr += data.toString()
    })

    proc.on('close', (code) => {
      if (code === 0) {
        resolve(stdout)
      } else {
        reject(new Error(`tmux command failed: ${stderr}`))
      }
    })
  })
}

// Capture pane content
async function capturePane(sessionName: string): Promise<string> {
  return await tmux(['capture-pane', '-t', sessionName, '-p'])
}

// Main test function
async function testCLIWithTmux() {
  const sessionName = 'savant-code-test-' + Date.now()

  console.log('🚀 Starting tmux-based CLI test...')
  console.log(`📦 Session: ${sessionName}`)

  // 1. Check if tmux is installed
  if (!isTmuxAvailable()) {
    console.error('❌ tmux not found')
    console.error('\n📦 Installation:')
    console.error('  macOS:   brew install tmux')
    console.error('  Ubuntu:  sudo apt-get install tmux')
    console.error('  Windows: Use WSL and run sudo apt-get install tmux')
    console.error(
      '\nℹ️  This is just a proof-of-concept. See the documentation for alternatives.',
    )
    process.exit(1)
  }

  try {
    const version = await tmux(['-V'])
    console.log(`✅ tmux is installed: ${version.trim()}`)

    // 2. Create new detached tmux session running the CLI
    console.log('\n📺 Creating tmux session...')
    await tmux([
      'new-session',
      '-d',
      '-s',
      sessionName,
      '-x',
      '120', // width
      '-y',
      '30', // height
      'bun',
      'run',
      'src/index.tsx',
      '--help',
    ])
    console.log('✅ Session created')

    // 3. Wait for CLI to start
    await sleep(1000)

    // 4. Capture initial output
    console.log('\n📸 Capturing initial output...')
    const initialOutput = await capturePane(sessionName)
    const cleanOutput = stripAnsi(initialOutput)

    console.log('\n--- Output ---')
    console.log(cleanOutput)
    console.log('--- End Output ---\n')

    // 5. Verify output contains expected text
    const checks = [
      { text: '--agent', pass: cleanOutput.includes('--agent') },
      { text: 'Usage:', pass: cleanOutput.includes('Usage:') },
      { text: '--help', pass: cleanOutput.includes('--help') },
    ]

    console.log('🔍 Verification:')
    checks.forEach(({ text, pass }) => {
      console.log(
        `  ${pass ? '✅' : '❌'} Contains "${text}"${pass ? '' : ' - NOT FOUND'}`,
      )
    })

    const allPassed = checks.every((c) => c.pass)
    console.log(
      `\n${allPassed ? '🎉 All checks passed!' : '⚠️  Some checks failed'}`,
    )

    // 6. Example: Send interactive command (commented out for --help test)
    /*
    console.log('\n⌨️  Sending test command...')
    await sendKeys(sessionName, 'hello world')
    await sendKeys(sessionName, 'Enter')
    await sleep(2000)

    const responseOutput = await capturePane(sessionName)
    console.log('\n--- Response ---')
    console.log(stripAnsi(responseOutput))
    console.log('--- End Response ---')
    */
  } catch (error) {
    console.error('\n❌ Test failed:', error)
  } finally {
    // 7. Cleanup: kill the tmux session
    console.log('\n🧹 Cleaning up...')
    try {
      await tmux(['kill-session', '-t', sessionName])
      console.log('✅ Session cleaned up')
    } catch (e) {
      console.log('⚠️  Session may have already exited')
    }
  }
}

// Run the test
testCLIWithTmux().catch(console.error)

import { afterEach, beforeEach, describe, expect, test } from 'bun:test'
import React from 'react'
import { renderToStaticMarkup } from 'react-dom/server'

import { initializeThemeStore } from '../../hooks/use-theme'
import { useChatStore } from '../../state/chat-store'
import { useMessageBlockStore } from '../../state/message-block-store'
import { chatThemes, createMarkdownPalette } from '../../utils/theme-system'
import { MessageWithAgents } from '../message-with-agents'

import type { ChatMessage } from '../../types/chat'
import type { MarkdownPalette } from '../../utils/markdown-renderer'

initializeThemeStore()

const theme = chatThemes.light
const basePalette: MarkdownPalette = createMarkdownPalette(theme)

// -----------------------------------------------------------------------------
// Helper factory functions for creating test messages
// -----------------------------------------------------------------------------

const createUserMessage = (id: string, content: string): ChatMessage => ({
  id,
  variant: 'user',
  content,
  timestamp: new Date().toISOString(),
})

const createAiMessage = (id: string, content: string): ChatMessage => ({
  id,
  variant: 'ai',
  content,
  timestamp: new Date().toISOString(),
})

const createAgentMessage = (
  id: string,
  content: string,
  agentName: string,
  options: Partial<ChatMessage> = {},
): ChatMessage => ({
  id,
  variant: 'agent',
  content,
  timestamp: new Date().toISOString(),
  agent: {
    agentName,
    agentType: 'test-agent',
    responseCount: 1,
  },
  ...options,
})

const createErrorMessage = (id: string, content: string): ChatMessage => ({
  id,
  variant: 'error',
  content,
  timestamp: new Date().toISOString(),
})

// Creates an agent message without the required agent info (for error testing)
const createMalformedAgentMessage = (id: string, content: string): ChatMessage => ({
  id,
  variant: 'agent',
  content,
  timestamp: new Date().toISOString(),
  // Intentionally missing agent property
} as ChatMessage)

const createModeDividerMessage = (id: string, mode: string): ChatMessage => ({
  id,
  variant: 'ai',
  content: 'this content should be ignored',
  timestamp: new Date().toISOString(),
  blocks: [
    {
      type: 'mode-divider',
      mode,
    },
  ],
})

const defaultCallbacks = {
  onToggleCollapsed: () => {},
  onBuildFast: () => {},
  onBuildMax: () => {},
  onBuildLite: () => {},
  onFeedback: () => {},
  onCloseFeedback: () => {},
  onAdClick: () => {},
  onAdImpression: () => {},
  onResponseAdsNeeded: () => {},
}

const initializeStore = (overrides: {
  messageTree?: Map<string, ChatMessage[]>
  isWaitingForResponse?: boolean
  timerStartTime?: number | null
  availableWidth?: number
} = {}) => {
  useMessageBlockStore.setState({
    context: {
      theme,
      markdownPalette: basePalette,
      messageTree: overrides.messageTree ?? new Map<string, ChatMessage[]>(),
      isWaitingForResponse: overrides.isWaitingForResponse ?? false,
      timerStartTime: overrides.timerStartTime ?? null,
      availableWidth: overrides.availableWidth ?? 80,
      responseAds: {},
    },
    callbacks: defaultCallbacks,
  })
}

beforeEach(() => {
  initializeStore()
  useChatStore.setState({ streamingAgents: new Set<string>() })
})

afterEach(() => {
  useMessageBlockStore.getState().reset()
  useChatStore.setState({ streamingAgents: new Set<string>() })
})

const baseMessageWithAgentsProps = {
  depth: 0,
  isLastMessage: false,
  availableWidth: 80,
}

// =============================================================================
// MessageBlockStore Tests - store behavior, not JS built-ins
// =============================================================================

describe('MessageBlockStore', () => {
  describe('setContext', () => {
    test('performs partial merge, preserving unspecified values', () => {
      // Set initial state with specific values
      initializeStore({
        isWaitingForResponse: true,
        timerStartTime: 12345,
        availableWidth: 100,
      })

      // Update only one value
      useMessageBlockStore.getState().setContext({
        isWaitingForResponse: false,
      })

      const state = useMessageBlockStore.getState()
      // Updated value should change
      expect(state.context.isWaitingForResponse).toBe(false)
      // Other values should be preserved
      expect(state.context.timerStartTime).toBe(12345)
      expect(state.context.availableWidth).toBe(100)
      expect(state.context.theme).toBe(theme)
    })

    test('updates messageTree without affecting other context values', () => {
      const child1 = createAgentMessage('child-1', 'Content 1', 'Agent One')
      const child2 = createAgentMessage('child-2', 'Content 2', 'Agent Two')
      const newTree = new Map<string, ChatMessage[]>([
        ['parent-1', [child1, child2]],
      ])

      useMessageBlockStore.getState().setContext({
        messageTree: newTree,
      })

      const state = useMessageBlockStore.getState()
      expect(state.context.messageTree).toBe(newTree)
      expect(state.context.messageTree?.get('parent-1')).toHaveLength(2)
      // Theme should be unchanged
      expect(state.context.theme).toBe(theme)
    })

    test('can update multiple context values at once', () => {
      useMessageBlockStore.getState().setContext({
        isWaitingForResponse: true,
        timerStartTime: 99999,
        availableWidth: 200,
      })

      const state = useMessageBlockStore.getState()
      expect(state.context.isWaitingForResponse).toBe(true)
      expect(state.context.timerStartTime).toBe(99999)
      expect(state.context.availableWidth).toBe(200)
    })
  })

  describe('setCallbacks', () => {
    test('replaces entire callbacks object', () => {
      const mockToggle = () => {}
      const mockBuildFast = () => {}
      const mockBuildMax = () => {}
      const mockBuildFree = () => {}
      const mockFeedback = () => {}
      const mockCloseFeedback = () => {}

      useMessageBlockStore.getState().setCallbacks({
        onToggleCollapsed: mockToggle,
        onBuildFast: mockBuildFast,
        onBuildMax: mockBuildMax,
        onBuildLite: mockBuildFree,
        onFeedback: mockFeedback,
        onCloseFeedback: mockCloseFeedback,
        onAdClick: () => {},
        onAdImpression: () => {},
        onResponseAdsNeeded: () => {},
      })

      const state = useMessageBlockStore.getState()
      expect(state.callbacks.onToggleCollapsed).toBe(mockToggle)
      expect(state.callbacks.onBuildFast).toBe(mockBuildFast)
      expect(state.callbacks.onBuildMax).toBe(mockBuildMax)
      expect(state.callbacks.onBuildLite).toBe(mockBuildFree)
      expect(state.callbacks.onFeedback).toBe(mockFeedback)
      expect(state.callbacks.onCloseFeedback).toBe(mockCloseFeedback)
    })

    test('callbacks are independent from context', () => {
      const originalTheme = useMessageBlockStore.getState().context.theme

      useMessageBlockStore.getState().setCallbacks({
        ...defaultCallbacks,
        onToggleCollapsed: () => console.log('new toggle'),
      })

      // Context should be unchanged
      expect(useMessageBlockStore.getState().context.theme).toBe(originalTheme)
    })
  })

  describe('reset', () => {
    test('restores context to initial state', () => {
      // Modify state significantly
      useMessageBlockStore.getState().setContext({
        isWaitingForResponse: true,
        timerStartTime: 12345,
        availableWidth: 200,
        messageTree: new Map([['key', [createAgentMessage('a', 'b', 'c')]]]),
      })

      useMessageBlockStore.getState().reset()

      const state = useMessageBlockStore.getState()
      expect(state.context.theme).toBeNull()
      expect(state.context.isWaitingForResponse).toBe(false)
      expect(state.context.timerStartTime).toBeNull()
      expect(state.context.availableWidth).toBe(80)
    })

